// Low-resolution authoring previews are independent of production benchmarks.
// Cache by reachable content, not node ID or layout. Never read back GPU maps.
import {compileGraph,graphAtNode,nodeFingerprint} from './model.js';
import {executeCPU,maps,maskValue,uvAt,packMaps,blendWeight,srgb} from './pixels.js';
import {loadSource} from './assets.js';
const cache=new Map(),images=new Map();let cancellation=0;
async function image(out,channel){const n=out.size,g=n/8,core=n*.75,pixels=new Uint8ClampedArray(core*core*4),source=channel==='normal'?out.normal:channel==='color'?out.color:out.surface,c={ao:0,roughness:1,metalness:2,height:3}[channel];for(let y=0;y<core;y++)for(let x=0;x<core;x++){const from=((g+core-1-y)*n+g+x)*4,to=(y*core+x)*4;for(let k=0;k<3;k++)pixels[to+k]=c===undefined?source[from+k]:source[from+c];pixels[to+3]=255;}const canvas=new OffscreenCanvas(core,core);canvas.getContext('2d').putImageData(new ImageData(pixels,core,core),0,0);return new FileReaderSync().readAsDataURL(await canvas.convertToBlob({type:'image/png'}));}
self.onmessage=async({data})=>{if(data.cancel){cancellation++;return;}const epoch=cancellation;const {id,graph,size=64,libraryId,graphKey}=data;try{for(const n of graph.nodes){if(epoch!==cancellation)break;try{let program,root,out,cached=false,computeMs=0;const begin=performance.now();if(n.kind==='noise'){root={kind:n.kind,params:n.params,inputs:{}};const key='mask:'+size+':'+nodeFingerprint(root);cached=cache.has(key);out=cache.get(key);if(!out){out=maps(size);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const value=Math.round(maskValue(n.params,uvAt(x,size),uvAt(y,size))*255),at=(y*size+x)*4;const display=Math.round(srgb(value/255)*255);out.color.set([display,display,display,255],at);out.normal.set([128,128,255,255],at);out.surface.set([255,255,0,128],at);}cache.set(key,out);}}else{program=compileGraph(graphAtNode(graph,n.id));root=program.root;out=await executeCPU(program,size,loadSource,{cache,onNode:(node,ms,reused)=>{if(node===root){computeMs=ms;cached=reused;}}});}const key=size+':'+nodeFingerprint(root);let maskOut=null;if(n.kind==='buildingStage'&&out.masks&&root.params.enabled!==false){const c={damage:0,grime:1,runoff:2,deposition:3}[root.params.stage];if(c!==undefined){maskOut=maps(size);for(let i=0;i<out.masks.length;i+=4){const v=out.masks[i+c];const display=Math.round(srgb(v/255)*255);maskOut.color.set([display,display,display,255],i);maskOut.normal.set([128,128,255,255],i);maskOut.surface.set([255,255,0,128],i);}}}else if(n.kind==='blend'&&root.params.enabled!==false){const a=cache.get(size+':'+nodeFingerprint(root.inputs.base)),b=cache.get(size+':'+nodeFingerprint(root.inputs.layer));if(a&&b){maskOut=maps(size);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const i=(y*size+x)*4,v=Math.round(blendWeight(root.params,a,b,root.inputs.mask?.params,uvAt(x,size),uvAt(y,size),i)*255);const display=Math.round(srgb(v/255)*255);maskOut.color.set([display,display,display,255],i);maskOut.normal.set([128,128,255,255],i);maskOut.surface.set([255,255,0,128],i);}}}let thumbnails=images.get(key);if(!thumbnails){thumbnails={};for(const channel of ['color','normal','roughness','height','metalness','ao'])thumbnails[channel]=await image(out,channel);images.set(key,thumbnails);while(images.size>128)images.delete(images.keys().next().value);}if(maskOut)thumbnails={...thumbnails,mask:await image(maskOut,'color')};const maskBytes=maskOut?packMaps(maskOut,{name:'Placement mask'},'authoring-mask'):null;const bytes=packMaps(out,{name:'Intermediate authoring preview',weather:program?.graph?.weather},'authoring-preview');self.postMessage({id,graphKey,nodeId:n.id,libraryId,size,images:thumbnails,bytes,maskBytes,computeMs,cached,totalMs:performance.now()-begin},[bytes.buffer,...(maskBytes?[maskBytes.buffer]:[])]);}catch(error){self.postMessage({id,nodeId:n.id,libraryId,error:error.message});}}self.postMessage({id,done:true,libraryId});}catch(error){self.postMessage({id,done:true,error:error.message,libraryId});}};
